		/**
		* 获取当前套餐信息（Issue #97550 新接口链路）。
		* api1 出余额/档位，api2 出付费明细与续费标记，api3 出免费包与切片额度。
		*/
		async getCurrentPlan() {
			const defaultPlan = {
				isPro: false,
				expireAt: 0,
				renewFlag: 0,
				PackageCode: void 0,
				name: ""
			};
			try {
				const isInternationalVersion = document?.body?.getAttribute("data-is-chinese-version") === "false";
				const storedLang = typeof localStorage !== "undefined" ? localStorage.getItem("CODEBUDDY_IDE_STORAGE_LANG") : null;
				const acceptLanguage = storedLang ? storedLang.toLowerCase().startsWith("en") ? "en" : "zh" : isInternationalVersion ? "en" : "zh";
				const { resources, summary, failedSources } = await fetchUserResources({
					fetchSummary: () => this.fetchResourceSummary(acceptLanguage),
					fetchPaidPackages: (params) => this.fetchResourcePackagesPage("/billing/meter/get-user-resource-paid-packages", "paid", acceptLanguage, params, { NeedRenewInfo: true }),
					fetchFreePackages: (params) => this.fetchResourcePackagesPage("/billing/meter/get-user-resource-free-packages", "free", acceptLanguage, params, buildSlicePeriodRange()),
					warn: (message) => console.warn(`[BackendProvider] ${message}`),
					resourceId: (item) => String(item?.ResourceId ?? "")
				});
				if (failedSources.length > 0) console.warn(`[BackendProvider] ${failedSources.length} of 3 resource sources failed after retries (${failedSources.join(", ")}); credits are incomplete`);
				if (!resources || resources.length === 0) return defaultPlan;
				const parseTime = (time) => {
					if (!time) return 0;
					if (typeof time === "string" && /^\d+$/.test(time)) return new Date(Number(time)).getTime();
					return new Date(time).getTime();
				};
				const dailyCredits = [CommodityCode.free];
				const onlyRefreshCodes = [
					CommodityCode.proMon,
					CommodityCode.proMonPlus,
					CommodityCode.proYear,
					CommodityCode.freeMon,
					CommodityCode.youth,
					CommodityCode.advanced,
					CommodityCode.flagship,
					CommodityCode.bonus28,
					CommodityCode.freeMonIntl,
					CommodityCode.proTrialMon,
					CommodityCode.proTrialYear,
					CommodityCode.bonusIntl
				];
				const onlyExpireCodes = [
					CommodityCode.activity,
					CommodityCode.extra,
					CommodityCode.extra38,
					CommodityCode.bonus29,
					CommodityCode.bonus30,
					CommodityCode.extraIntl
				];
				const planResources = resources.map((r) => {
					const isDaily = dailyCredits.includes(r.PackageCode);
					const endTime = isDaily ? r.CycleEndTime : r.DeductionEndTime;
					const refreshAt = parseTime(r.CycleEndTime) + 1e3;
					const startAt = parseTime(r.DeductionStartTime) || parseTime(r.CycleStartTime) || void 0;
					const showExpireAt = !onlyRefreshCodes.includes(r.PackageCode);
					const showRefreshAt = !onlyExpireCodes.includes(r.PackageCode);
					const capacity = resolveResourceCapacity(r);
					return {
						id: r.ResourceId,
						name: isDaily ? "plan.addonCredits" : isInternationalVersion ? r.PackageName : getPackageName(r.PackageCode),
						packageCode: r.PackageCode,
						isDaily,
						total: capacity.total,
						used: capacity.used,
						left: capacity.left,
						startAt,
						expireAt: parseTime(endTime),
						refreshAt: isDaily ? void 0 : refreshAt,
						showExpireAt,
						showRefreshAt
					};
				}).sort((a, b) => {
					const getPriority = (code) => {
						if ([
							CommodityCode.proMon,
							CommodityCode.proMonPlus,
							CommodityCode.proYear,
							CommodityCode.freeMon,
							CommodityCode.youth,
							CommodityCode.advanced,
							CommodityCode.flagship,
							CommodityCode.freeMonIntl,
							CommodityCode.proTrialMon,
							CommodityCode.proTrialYear
						].includes(code)) return 1;
						if ([CommodityCode.bonus28, CommodityCode.bonusIntl].includes(code)) return 2;
						if ([
							CommodityCode.extra,
							CommodityCode.extra38,
							CommodityCode.extraIntl
						].includes(code)) return 3;
						if ([
							CommodityCode.activity,
							CommodityCode.bonus29,
							CommodityCode.bonus30
						].includes(code)) return 4;
						if ([CommodityCode.gift].includes(code)) return 5;
						if ([CommodityCode.free].includes(code)) return 6;
						console.warn("[BackendProvider] unknown packageCode for priority sorting, falling back to lowest priority:", code);
						return 7;
					};
					const priorityDiff = getPriority(a.packageCode) - getPriority(b.packageCode);
					if (priorityDiff !== 0) return priorityDiff;
					return (a.expireAt ?? Infinity) - (b.expireAt ?? Infinity);
				});
				const subscriptionPackageCode = summary?.subscriptionPackageCode ?? "";
				const planPool = resources;
				const proPlan = planPool.find((r) => r.PackageCode === CommodityCode.proYear || r.PackageCode === CommodityCode.proMon || r.PackageCode === CommodityCode.proMonPlus);
				const youthPlan = planPool.find((r) => r.PackageCode === CommodityCode.youth);
				const advancedPlan = planPool.find((r) => r.PackageCode === CommodityCode.advanced);
				const flagshipPlan = planPool.find((r) => r.PackageCode === CommodityCode.flagship);
				const trialPlan = planPool.find((r) => r.PackageCode === CommodityCode.gift || r.PackageCode === CommodityCode.freeMon || r.PackageCode === CommodityCode.proTrialMon || r.PackageCode === CommodityCode.proTrialYear);
				const activePlan = (subscriptionPackageCode ? planPool.find((r) => r.PackageCode === subscriptionPackageCode) : void 0) ?? (flagshipPlan || advancedPlan || proPlan || youthPlan || trialPlan);
				const summaryTotals = summary ? sumSummaryCapacity(summary) : (() => {
					const counted = excludeSuppressedPlanBase(planResources, isInternationalVersion);
					return {
						total: counted.reduce((sum, r) => sum + r.total, 0),
						left: counted.reduce((sum, r) => sum + r.left, 0),
						used: counted.reduce((sum, r) => sum + r.used, 0)
					};
				})();
				const totalUsageLeft = summaryTotals.left;
				const totalUsageTotal = summaryTotals.total;
				const totalUsageUsed = summaryTotals.used;
				if (activePlan) return {
					isPro: !!proPlan,
					isYouth: !!youthPlan,
					isAdvanced: !!advancedPlan,
					isFlagship: !!flagshipPlan,
					isTria: trialPlan ? [AccountStatus.valid, AccountStatus.usedUp].includes(trialPlan.Status) : false,
					expireAt: parseTime(activePlan.DeductionEndTime || activePlan.ExpiredTime || activePlan.CycleEndTime),
					refreshAt: parseTime(activePlan.CycleEndTime),
					renewFlag: Number(activePlan.AutoRenewFlag) === 1 ? 1 : 0,
					PackageCode: activePlan.PackageCode,
					name: isInternationalVersion ? activePlan.PackageName : getPackageName(activePlan.PackageCode),
					usageTotal: String(totalUsageTotal),
					usageUsed: String(totalUsageUsed),
					usageLeft: String(totalUsageLeft),
					resources: planResources
				};
				return {
					...defaultPlan,
					usageTotal: String(totalUsageTotal),
					usageUsed: String(totalUsageUsed),
					usageLeft: String(totalUsageLeft),
					resources: planResources
				};
			} catch (error) {
				console.error("[BackendProvider] getCurrentPlan error:", error);
				return defaultPlan;
			}
		}
