		async getSkillHubDetail(slug) {
			const trimmed = (slug || "").trim();
			const sep = trimmed.startsWith("@") ? trimmed.indexOf("/") : -1;
			const hasNamespace = sep > 1 && sep < trimmed.length - 1;
			const bareSlug = hasNamespace ? trimmed.slice(sep + 1) : trimmed;
			const qs = hasNamespace ? `?namespace=${encodeURIComponent(trimmed.slice(1, sep))}` : "";
			const res = await this.skillHubFetch(`${BackendProvider.SKILLHUB_BASE_URL}/api/v1/skills/${encodeURIComponent(bareSlug)}${qs}`);
			if (!res.ok) throw new Error(`SkillHub detail: ${res.status}`);
			return res.json();
		}
		async getSkillHubExists(slugs) {
			const res = await this.skillHubFetch(`${BackendProvider.SKILLHUB_BASE_URL}/api/v1/skills/exists`, {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify({ slugs })
			});
			if (!res.ok) throw new Error(`SkillHub exists: ${res.status}`);
			return res.json();
		}
