	if (!filePath) return "";
	if (/^[a-zA-Z]:[/\\]/.test(filePath)) return `vscode-file://vscode-app/${filePath.replace(/\\/g, "/")}`;
	if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(filePath)) return filePath;
